CREATE TABLE IF NOT EXISTS alert_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, metric TEXT NOT NULL, operator TEXT NOT NULL CHECK(operator IN ('>=','<=')), threshold REAL NOT NULL, email TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, last_state INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alert_history (id INTEGER PRIMARY KEY AUTOINCREMENT, rule_id INTEGER NOT NULL, observed_value REAL NOT NULL, triggered_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, delivery_status TEXT NOT NULL DEFAULT 'pending', FOREIGN KEY(rule_id) REFERENCES alert_rules(id));